package com.eugenia.orders.domain;
import java.math.BigDecimal; import java.util.List;
public final class OrderModels { private OrderModels(){} public record Item(String productId,int quantity,BigDecimal unitPrice,TaxCategory taxCategory){} public record Line(String productId,int quantity,BigDecimal unitPrice,BigDecimal grossSubtotal,BigDecimal discount,BigDecimal netSubtotal,BigDecimal tax,BigDecimal total){} public record Totals(BigDecimal grossSubtotal,BigDecimal discount,BigDecimal netSubtotal,BigDecimal tax,BigDecimal grandTotal){} public record Calculation(List<Line> lines,Totals totals){} public record Client(String clientId,boolean active,Segment segment,TaxRegime taxRegime,Market market){} public record Product(String productId,boolean active,TaxCategory taxCategory){} }
